  "Small Lightning Elemental": {
    legs: 0,
    arms: 2,
    source: "Bestiary 2",
    creatureType: "outsider",
    subTypes: [
      "air",
      "elemental",
      "extraplanar"
    ],
    alignments: [
      "Neutral"
    ],
    size: "Small",
    hd: 2,
    hdVal: 10,
    cr: 1,
    racialFeatures: [
      "Darkvision 60 ft."
    ],
    speed: {
      maneuverability: "Perfect",
      fly: 100
    },
    abilities: {
      str: 10,
      dex: 15,
      con: 10,
      int: 4,
      wis: 11,
      cha: 11
    },
    feats: [
      {
        name: "Improved Initiative",
        type: "Combat"
      },
      {
        name: "Weapon Finesse",
        type: "Combat"
      }
    ],
    attacks: [
      {
        weapon: "Slam",
        name: "Slam",
        damage: "1d4",
        bonuses: [
          {
            source: "inherent",
            value: "1d3",
            appliesTo: "damageType",
            damageType: "electricity"
          }
        ],
        type: "primary"
      }
    ],
    immunities: [
      "Immune to electricity"
    ],
    defense: {
      naturalArmor: 1
    },
    space: "5 ft.",
    reach: "5 ft.",
    environment: "any (Plane of Air)",
    visualDescription: "This creature looks like a dark storm cloud, with sparks suggesting eyes and long sweeping arms charged with bolts of lightning.",
    description: "Though most think of the Plane of Air as a vast expanse of clear sky, that plane also holds the power of the storm, including monstrous hurricanes larger than entire worlds and thunderstorms whose peals and claps can shatter stone. Whether lightning elementals are the byproduct of common air elementals spending too much time near these electrically charged storms or are merely calved off like forgotten flurries, they are aggressive and almost suicidal in their willingness to leap into battle. They particularly enjoy attacking creatures that are made of metal and creatures that wear metal armor or wield metal weapons. Many lightning elementals have a roughly humanoid shape, but some prefer animalistic shapes (particularly birds and dragons), and a few appear to be nothing more than large disembodied heads made of dark clouds with flickering lightning tongues. Regardless of the shape a lightning elemental takes, the air around the creature hums and throbs with the promise of electrocution and the tangy stink of ozone.",
    organization: "solitary, pair, or gang (3-8)",
    languages: "Auran",
    spellLikeAbilities: [],
    skills: {
      Acrobatics: {
        ranks: 5
      },
      "Escape Artist": {
        ranks: 4
      },
      Fly: {
        ranks: 0
      },
      "Knowledge (planes)": {
        ranks: 1
      },
      Perception: {
        ranks: 2
      }
    },
    special: {
      "metal mastery": {
        type: "Ex",
        text: "A lightning elemental gains a +3 bonus on attack rolls if its opponent is wearing metal armor, is wielding a metal weapon, or is made of metal (such as an iron golem)."
      },
      "spark leap": {
        type: "Ex",
        text: "A lightning elemental gains a +10 bonus on bull rush, disarm, overrun, and trip attacks when it charges a creature against whom its metal mastery ability applies."
      }
    }
  },

